DECLARE @actor nvarchar(128)=?,@now datetimeoffset(7)=?,@reason nvarchar(120)=?,@id bigint=?,@version bigint=?; DECLARE @changed TABLE(id bigint); UPDATE dbo.m_student SET is_deleted=1,deleted_at=@now,deleted_by=@actor,delete_reason=@reason,updated_at=@now,updated_by=@actor,row_version=row_version+1 OUTPUT INSERTED.student_id INTO @changed WHERE student_id=@id AND row_version=@version AND is_deleted=0; SELECT id FROM @changed;
